import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第四册：流利英语 · Lesson 9 Royal espionage","description":"学习 过去完成时与过去叙事参照点，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 9 Royal espionage","description":"学习 过去完成时与过去叙事参照点，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 过去完成时与过去叙事参照点，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 8 Trading standards","link":"/life/english/new-concept/book-4/unit-01/lesson-008"},"next":{"text":"第四册：流利英语 · Lesson 10 Silicon Valley","link":"/life/english/new-concept/book-4/unit-02/lesson-010"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 8 Trading standards","link":"/life/english/new-concept/book-4/unit-01/lesson-008"},"next":{"text":"第四册：流利英语 · Lesson 10 Silicon Valley","link":"/life/english/new-concept/book-4/unit-02/lesson-010"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-02/lesson-009.md","filePath":"life/english/new-concept/book-4/unit-02/lesson-009.md"}'),i={name:"life/english/new-concept/book-4/unit-02/lesson-009.md"};function l(r,e,s,d,h,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第四册-流利英语-·-lesson-9-royal-espionage" tabindex="-1">第四册：流利英语 · Lesson 9 Royal espionage <a class="header-anchor" href="#第四册-流利英语-·-lesson-9-royal-espionage" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 9 Royal espionage&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>以历史谍报叙事训练时间线阅读：人物何时获悉消息，行动又发生在消息传递之前还是之后。把直接观察、传闻与后来解释分开，不把一位叙事者的描绘当成所有历史人物的动机。写作时用过去完成时交代关键前情，再用一般过去时推进故事。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>espionage</td><td>/ˈespiənɑːʒ/</td><td>n.</td><td>间谍活动</td><td>industrial espionage</td></tr><tr><td>messenger</td><td>/ˈmesɪndʒə/</td><td>n.</td><td>信使</td><td>a royal messenger</td></tr><tr><td>intercept</td><td>/ˌɪntəˈsept/</td><td>v.</td><td>截获</td><td>intercept a letter</td></tr><tr><td>rumour</td><td>/ˈruːmə/</td><td>n.</td><td>传闻</td><td>spread a rumour</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>pass on — 转交信息</li><li>keep track of — 持续掌握动态</li></ul><h2 id="语法讲解-过去完成时与过去叙事参照点" tabindex="-1">语法讲解：过去完成时与过去叙事参照点 <a class="header-anchor" href="#语法讲解-过去完成时与过去叙事参照点" aria-label="Permalink to &quot;语法讲解：过去完成时与过去叙事参照点&quot;">​</a></h2><p>过去完成时 had done 表示早于某个过去参照点的动作，并不是所有“很久以前”的动作都要用它。先叙述收到消息，再回到消息形成的时刻，适合使用 had done；时间先后已经由 before 清楚表示时，一般过去时有时也可成立。进入回顾段落后不必每句机械重复过去完成时。过去完成时的否定为 had not done，不能再加 did。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>By the time the messenger arrived, the clerk had hidden the letter.</p></blockquote><p>信使到达时，书记员已经藏起了信。</p><p>arrived 是过去参照点；had hidden 表示藏信发生在到达之前；by the time 引出截止时间。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>不能仅因故事发生在古代就整篇用 had done；先确定两个过去动作的关系。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>读 by the time 从句后停顿；重读 had hidden，用时间轴核对录音是否表达出“先藏后到”。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The archivist received a sealed envelope on Monday. Someone had stored it behind a cabinet for years. She compared the handwriting with an earlier letter.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>创作三句档案馆小故事：先收到一封旧信，说明它此前经历了什么，再写调查动作。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>过去完成时只承担前情说明，第三句回到主线的一般过去时。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>示例中谁先发生：藏信还是信使到达？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 藏信。</p><p><strong>解析：</strong> had hidden 早于 arrived。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>填空：The officer discovered that someone ___ opened the box.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> had</p><p><strong>解析：</strong> 发现之前的开箱用过去完成时。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>把 had hidden 改为否定形式。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> had not hidden</p><p><strong>解析：</strong> not 放在助动词 had 后。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：过去完成时与过去叙事参照点。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-008">上一课</a> · <a href="/life/english/new-concept/book-4/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-02/lesson-010">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(i,[["render",l]]);export{u as __pageData,b as default};
